#!/usr/bin/env php
<?php

declare(strict_types=1);

/**
 * Lane-close agent session capture.
 *
 * While the Solo DB row for <solo-process-id> is alive, resolve provider/cwd/started_at
 * and extract that session's transcript via exact "Solo process ID: <id>" marker join
 * into staging .orbit/agent-sessions/<provider>/<lane-slug>/.
 *
 * Exact marker join: the marker text must select exactly one runtime-scoped provider
 * session candidate. Ambiguity or zero matches = loud failure with diagnostics.
 */

// Robust arg parsing for mixed positional id + long options (works under test Process exec too)
$rawArgv = $GLOBALS['argv'] ?? $_SERVER['argv'] ?? [];
$script = array_shift($rawArgv); // drop script name

$soloProcessId = null;
$options = [];

foreach ($rawArgv as $a) {
    if (preg_match('/^--([a-z0-9-]+)(?:=(.*))?$/', $a, $m)) {
        $key = str_replace('-', '_', $m[1]);
        $val = $m[2] ?? true;
        $options[$key] = $val;
    } elseif ($soloProcessId === null && preg_match('/^\d+$/', $a)) {
        $soloProcessId = (int) $a;
    } elseif (preg_match('/^--solo-process-id=(.+)$/', $a, $m)) {
        $soloProcessId = (int) $m[1];
    }
}

if (array_key_exists('help', $options) || $soloProcessId === null) {
    fwrite(STDOUT, <<<'EOF'
Usage:
  bin/orbit-agent-session-capture <solo-process-id> [--home=...] [--cwd=...] [--solo-db=...] [--orbit-dir=...]

Extracts the provider session for the given live Solo process id using exact marker match
"Solo process ID: <id>" (and close variants). Writes staged capture under
.orbit/agent-sessions/<provider>/<slug>/ containing manifest.json, usage.json,
messages.jsonl, and raw/ copies.

Exits non-zero with diagnostics on missing or ambiguous marker match.
EOF);
    exit($soloProcessId === null ? 2 : 0);
}

if ($soloProcessId <= 0) {
    fwrite(STDERR, "solo-process-id is required and must be positive\n");
    exit(2);
}

$home = (string) ($options['home'] ?? getenv('HOME'));
$cwd = realpath((string) ($options['cwd'] ?? getcwd())) ?: (string) ($options['cwd'] ?? getcwd());
$soloDb = (string) ($options['solo_db'] ?? $options['solo-db'] ?? "{$home}/.config/soloterm/solo.db");
$orbitDir = (string) ($options['orbit_dir'] ?? $options['orbit-dir'] ?? ($cwd.'/.orbit'));
$explicitProvider = $options['provider'] ?? null;
$explicitSlug = $options['slug'] ?? null;

if (! is_file($soloDb)) {
    fwrite(STDERR, "solo db not found: {$soloDb}\n");
    exit(2);
}

$processRow = loadSoloProcessRow($soloDb, $soloProcessId);

if ($processRow === null) {
    // Try spawned_processes as fallback for runtime liveness
    $processRow = loadSoloSpawnedProcess($soloDb, $soloProcessId);
}

if ($processRow === null) {
    fwrite(STDERR, "solo process {$soloProcessId} not found in solo db (row not alive)\n");
    exit(2);
}

$kind = strtolower((string) ($processRow['kind'] ?? $processRow['process_kind'] ?? 'command'));
$command = (string) ($processRow['command'] ?? '');
$workingDir = realpath((string) ($processRow['working_dir'] ?? $processRow['project_path'] ?? $cwd)) ?: $cwd;
$name = (string) ($processRow['name'] ?? $processRow['process_name'] ?? 'agent');

$provider = $explicitProvider ?: inferProviderFromCommandOrName($command, $name, $kind);

// Resolve started_at from Solo row (prefer runtime spawned_at when the row is alive)
$startedAt = $processRow['spawned_at']
    ?? $processRow['created_at']
    ?? $processRow['started_at']
    ?? null;

fwrite(STDERR, sprintf(
    "resolved from solo.db: solo_process_id=%d provider=%s cwd=%s started_at=%s\n",
    $soloProcessId,
    $provider,
    $workingDir,
    $startedAt ?? 'null'
));

$slug = $explicitSlug ?: slugify($name ?: 'process-'.$soloProcessId).'-'.$soloProcessId;

$stagingBase = rtrim($orbitDir, '/').'/agent-sessions/'.$provider.'/'.$slug;
ensureDirectory($stagingBase);
ensureDirectory($stagingBase.'/raw');

$markerNeedle = "Solo process ID: {$soloProcessId}";

$extract = match ($provider) {
    'codex' => captureCodexExact($home, $workingDir, $soloProcessId, $markerNeedle, $startedAt),
    'claude' => captureClaudeExact($home, $workingDir, $soloProcessId, $markerNeedle),
    'grok' => captureGrokExact($home, $workingDir, $soloProcessId, $markerNeedle),
    default => [
