function loadSoloProcessRow(string $dbPath, int $id): ?array
{
    try {
        $db = new PDO('sqlite:'.$dbPath);
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        $columns = tableColumns($db, 'processes');
        $selectedColumns = array_values(array_filter(
            ['id', 'name', 'command', 'working_dir', 'kind', 'project_id', 'started_at', 'created_at', 'spawned_at'],
            fn (string $column): bool => in_array($column, $columns, true),
        ));

        if (! in_array('id', $selectedColumns, true)) {
            return null;
        }

        $select = implode(', ', array_map(quoteIdentifier(...), $selectedColumns));
        $stmt = $db->prepare("SELECT {$select} FROM processes WHERE id = ?");
        $stmt->execute([$id]);
        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        return $row ?: null;
    } catch (Throwable $e) {
        return null;
    }
}

